/*БД салон красоты.
С помощью этой базы можно качественно анализировать данные, без которых сложно растить и развивать бизнес,такие как рост/падение, посещаемость, 
выручка и чистая прибыль и т.д. Также в ней удобно хранить данные о клиентах которые необходимы для построения качественной клиентоориентированности и лояльности.*/



DROP DATABASE IF EXISTS beauty_saloon;
CREATE DATABASE beauty_saloon;
USE beauty_saloon;

DROP TABLE IF EXISTS employees;
CREATE TABLE employees(
	id_employee SERIAL PRIMARY KEY, 
    full_name VARCHAR(70),
    gender CHAR(1),
    birthday DATE,
    phone BIGINT,
    date_of_employment DATETIME DEFAULT NOW(),
    job_position VARCHAR(30),
	experience FLOAT,
    INDEX full_name_idx(full_name),
    INDEX job_position_idx(job_position)
);

