DROP TABLE IF EXISTS clients;
CREATE TABLE clients(
	id_client SERIAL PRIMARY KEY, 
    full_name VARCHAR(70), 
    gender CHAR(1),
    birthday DATE,
    phone BIGINT,
    total_spend_sum FLOAT, -- сколько потрачено всего(денег)
    card_registration_date DATE, -- дата заведения карты
    INDEX client_name_idx(full_name), 
    INDEX client_phone_idx(phone)
);

