DROP TABLE IF EXISTS offices; -- кабинеты
CREATE TABLE offices(
	id_office SERIAL PRIMARY KEY, 
    office_name VARCHAR(20), -- название кабинета
    employee1_id BIGINT UNSIGNED NOT NULL, -- связь с мастерами
    employee2_id BIGINT UNSIGNED NOT NULL,
	FOREIGN KEY (employee1_id) REFERENCES employees(id_employee),-- 1 к 1
	FOREIGN KEY (employee2_id) REFERENCES employees(id_employee)
);

