DROP TABLE IF EXISTS services;
CREATE TABLE services(
	id_service SERIAL PRIMARY KEY, 
    service_name VARCHAR(100), -- услуга
    office_id BIGINT UNSIGNED NOT NULL, -- зал
    cost FLOAT,  -- себестоимость
 	priсe FLOAT, -- цена
    cost_of_the_master FLOAT, -- зп мастера с услуги
    INDEX service_name_idx(service_name),
    FOREIGN KEY (office_id) REFERENCES offices(id_office) -- 1 к 1
);

