DROP TABLE IF EXISTS appointments; -- записи
CREATE TABLE appointments(
	id_appointment SERIAL PRIMARY KEY, 
    client_id BIGINT UNSIGNED NOT NULL, -- клиент -- с клиентами
    employee_id BIGINT UNSIGNED NOT NULL, -- сотрудники
    service_id BIGINT UNSIGNED NOT NULL,  -- услуги
    service_name VARCHAR(100),
    visit_date DATE, -- дата посещения
    backup_employee BIGINT UNSIGNED NOT NULL, -- запасной мастер
    INDEX appointments_visit_date_idx(visit_date),
	INDEX appointments_client_idx(client_id),
	FOREIGN KEY (employee_id) REFERENCES employees(id_employee), -- М к 1
	FOREIGN KEY (backup_employee) REFERENCES employees(id_employee), -- М к 1
    FOREIGN KEY (client_id) REFERENCES clients(id_client), -- 1 к 1
    FOREIGN KEY (service_id) REFERENCES services(id_service), -- М к М, потому что несколько коло в таб записи ссылаются на кол в таб услуги
    FOREIGN KEY (service_name) REFERENCES services(service_name) -- М к М, потому что несколько коло в таб записи ссылаются на кол в таб услуги
);

