DROP TABLE IF EXISTS stock; -- запасы
CREATE TABLE stock(
	product_id SERIAL PRIMARY KEY, 
    amount_in_stock INT, -- кол-во на складе -- с зак рас
    min_amount INT, -- мин необ кол-во
    unit_cost FLOAT,  -- закуп. цена за ед. с НДС
 	used_in_service BIGINT UNSIGNED NOT NULL, -- испол в услуге -- связь с наименованием услуги
 	INDEX product_id_amount_idx(product_id,amount_in_stock), -- остаток/наличие 
 	FOREIGN KEY (used_in_service) REFERENCES services(id_service) -- 1 к 1
);

