DROP VIEW IF EXISTS employee_information; -- представление для удобного вывода всей, или части, нужной информации по мастерам салона. 

CREATE VIEW employee_information AS
    SELECT employees.id_employee,
    employees.full_name,
    employees.job_position,
    offices.office_name,
    medical_record_status.expiration_date,
    medical_record_status.status 
FROM 
employees, offices, medical_record_status 
WHERE (employees.id_employee = offices.employee1_id OR employees.id_employee = offices.employee2_id)
AND employees.id_employee = medical_record_status.employee_id;

-- SELECT * FROM employee_information;

DROP VIEW IF EXISTS product_information; -- информация о продуктах

CREATE VIEW product_information AS
	SELECT stock.product_id,
	stock.amount_in_stock,
	stock.min_amount,
	stock.unit_cost,
	consumables_orders.supplier
FROM
stock,consumables_orders
WHERE stock.product_id = consumables_orders.product_id;

SELECT * FROM product_information;

DROP PROCEDURE IF EXISTS sp_appointments_today; -- для просмотра записей на сегодня
DELIMITER //  
CREATE PROCEDURE sp_appointments_today ()  
BEGIN  
    SELECT 
    client_id,
    employee_id,
    service_name,
    visit_date
	FROM appointments WHERE CAST(visit_date AS date) = CURDATE();     
END //  
DELIMITER ;

-- CALL sp_appointments_today(); 

DROP PROCEDURE IF EXISTS sp_stock_needed; -- для просмотра, что надо закупить
DELIMITER //  
CREATE PROCEDURE sp_stock_needed ()  
BEGIN  
    SELECT 
    product_id, 
    amount_in_stock,
    min_amount,
    min_amount - amount_in_stock AS amount_to_buy
	FROM stock WHERE amount_in_stock < min_amount;
	-- SELECT min_amount - amount_in_stock AS amount_to_buy
	-- FROM stock;
END //  
DELIMITER ;

-- CALL sp_stock_needed (); 

DELIMITER $$
$$
CREATE DEFINER=`root`@`localhost` TRIGGER `restock` AFTER UPDATE ON `stock` FOR EACH ROW BEGIN 
		IF NEW.amount_in_stock < NEW.min_amount THEN 
			SIGNAL SQLSTATE  '45000' SET MESSAGE_TEXT = 'Проверь расходники! Нужен дозаказ';
	END IF;
END 
$$
DELIMITER ;  -- Тригер 1

/*UPDATE stock -- Проверка работы тригера 1
SET
amount_in_stock = 1
WHERE amount_in_stock > 10;*/

DELIMITER $$
$$
CREATE DEFINER=`root`@`localhost` TRIGGER `expired_medical_book` AFTER INSERT ON `medical_record_status` FOR EACH ROW BEGIN 
		IF NEW.expiration_date <= curdate() THEN 
			SIGNAL SQLSTATE  '45000' SET MESSAGE_TEXT = 'Мед. книжка недействительна! Сотрудник не может приступить к работе!';
	END IF;
END
$$
DELIMITER ;  -- Тригер 2. 

