-- 1) Вывести 3- х клиентов (имя, пол, накопления)  с самыми большими накоплениями.

SELECT id_client, full_name, gender, total_spend_sum
FROM clients 
ORDER BY total_spend_sum DESC
LIMIT 3;

-- 2) Вывести всех сотрудников у которых заканчивается или закончилась мед книжка.

SELECT employees.id_employee, 
employees.full_name, 
medical_record_status.expiration_date,
datediff(medical_record_status.expiration_date,curdate()) AS days_left
FROM employees 
JOIN medical_record_status ON employees.id_employee = medical_record_status.employee_id AND datediff(medical_record_status.expiration_date,curdate()) <= 10
ORDER BY days_left;

-- 3) Определить сотрудника с самым высоким доходом за предыдущий месяц.

SELECT appointments.employee_id,
employees.full_name,
sum(round(services.cost_of_the_master,2)) AS salary
FROM appointments, employees, services
WHERE employees.id_employee = appointments.employee_id AND (MONTH(appointments.visit_date) = (MONTH(now())-1)) AND (YEAR(appointments.visit_date) = YEAR(now()))
GROUP BY appointments.employee_id, employees.full_name
ORDER BY salary DESC
LIMIT 1;

-- 4) Определить самую популярную услугу в салоне.

SELECT service_name,
count(service_name) 
FROM appointments
GROUP BY service_name 
ORDER BY count(service_name) DESC
LIMIT 1;

-- 5) Рассчитать чистую прибыль салона за 3 предыдущих года и этот, на сегодняшний момент.

SELECT 
sum(round((services.priсe - services.cost),2)) AS profit,
YEAR(appointments.visit_date) AS s_year
FROM appointments, services WHERE appointments.service_name = services.service_name AND YEAR(appointments.visit_date) >= YEAR(NOW()) - 3
GROUP BY s_year
ORDER BY s_year ASC;

-- 6) Определить насколько выросла/упала посещаемость салона за последнии 2 года, исходя из полученных данных предположить 
-- итоги посещаемости салона в этом году (будет рост или падение) 

SELECT 
COUNT(id_appointment) AS client_v,
YEAR(visit_date) AS v_year
FROM appointments WHERE YEAR(visit_date) >= YEAR(NOW()) - 2
GROUP BY v_year
ORDER BY v_year ASC;

-- предпологается рост.







